// Uma linha da planilha por INSCRITO na live.
//
// O payload vem de /api/save-lead. Nomes das chaves = nomes das COLUNAS: o
// cabecalho da planilha tem que bater exatamente com eles.

const linhas = [];

for (const item of $input.all()) {
  const b = item.json.body || item.json;

  const nome = String(b.nome || '').trim();
  const whatsapp = String(b.whatsapp || '');

  // Telefone como TEXTO: sem o apostrofo o Sheets come o '+' e transforma
  // +5511987654321 em notacao cientifica. E telefone quebrado nao dispara no
  // ManyChat.
  const whatsappCelula = whatsapp ? `'${whatsapp}` : '';

  const origem = [b.utm_source, b.utm_medium, b.utm_campaign, b.utm_content]
    .filter(Boolean)
    .join(' / ');

  linhas.push({
    json: {
      'Data/hora': b.data_hora_cadastro || '',
      'Nome': nome,
      'WhatsApp': whatsappCelula,
      'Live': b.evento_titulo || '',
      'Formulario': b.posicao === 'fim' ? 'fim da pagina' : 'topo da pagina',
      'Origem': origem,
      'gclid': b.gclid || '',
      'fbclid': b.fbclid || '',
      'lead_id': b.lead_id || '',
    },
  });
}

return linhas;
